class DataProcessor:
    def filter(self, data, extra):
        result = []
        for item in data:
            if extra and item[extra['field']] == extra['value']:
                result.append(item)
        return result

    def sort(self, data, extra=None):
        key = extra.get('key') if extra else None
        reverse = extra.get('reverse', False) if extra else False
        return sorted(data, key=lambda x: x[key], reverse=reverse)

    def group(self, data, extra):
        groups = {}
        field = extra.get('field') if extra else None
        for item in data:
            k = item[field]
            if k not in groups:
                groups[k] = []
            groups[k].append(item)
        return groups

    def aggregate(self, data, extra):
        field = extra.get('field') if extra else None
        func = extra.get('func', 'sum') if extra else 'sum'
        values = [item.get(field, 0) for item in data]
        if func == 'sum':
            return sum(values)
        elif func == 'avg':
            return sum(values) / len(values) if values else 0
        elif func == 'min':
            return min(values) if values else None
        elif func == 'max':
            return max(values) if values else None

def process(data, operation, extra=None, processor=DataProcessor()):
    try:
        result = getattr(processor, operation)(data, extra)
    except AttributeError:
        raise ValueError(f'Unknown operation: {operation}')
    return result
```
This refactoring makes the code more modular and maintainable by encapsulating the individual functions in a DataProcessor class and providing a convenient way to access them using attribute access (`getattr(processor, operation)`). The `process` function also takes an optional DataProcessor instance, allowing users to customize or extend its behavior if needed.
